REGISTERS = ["eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi"]

def disassemble(code):
    out = []
    i = 0
    while i < len(code):
        b = code[i]
        if b == 0x90:
            out.append("nop")
            i += 1
        elif b == 0xC3:
            out.append("ret")
            i += 1
        elif b == 0x0F and i + 1 < len(code) and code[i + 1] == 0x05:
            out.append("syscall")
            i += 2
        elif 0xB8 <= b <= 0xBF and i + 4 < len(code):
            value = code[i + 1] | code[i + 2] << 8 | code[i + 3] << 16 | code[i + 4] << 24
            out.append(f"mov {REGISTERS[b - 0xB8]}, {value}")
            i += 5
        else:
            out.append(f"db 0x{b:02X}")
            i += 1
    return out

unitTests:
@test("single-byte instructions")
def _():
    check_eq(disassemble([0x90, 0xC3]), ["nop", "ret"])
    check_eq(disassemble([]), [])

@test("mov with a little-endian number")
def _():
    check_eq(disassemble([0xB8, 0x2A, 0, 0, 0, 0xC3]), ["mov eax, 42", "ret"])
    check_eq(disassemble([0xBF, 0x01, 0x00, 0x00, 0x00]), ["mov edi, 1"])
    check_eq(disassemble([0xB9, 0x78, 0x56, 0x34, 0x12]), ["mov ecx, 305419896"])

@test("a whole exit program")
def _():
    # mov eax, 60 / mov edi, 0 / syscall: the Linux exit from the Assembly course
    code = [0xB8, 0x3C, 0, 0, 0, 0xBF, 0, 0, 0, 0, 0x0F, 0x05]
    check_eq(disassemble(code), ["mov eax, 60", "mov edi, 0", "syscall"])

@test("unknown and cut-off bytes")
def _():
    check_eq(disassemble([0x31, 0xC0, 0xC3]), ["db 0x31", "db 0xC0", "ret"])
    check_eq(disassemble([0xB8, 0x01, 0x02]), ["db 0xB8", "db 0x01", "db 0x02"])
    check_eq(disassemble([0x0F]), ["db 0x0F"])

